// Decodifica o conteúdo em Base64 recebido do GitHub
const raw = Buffer.from(
  $input.first().json.content,
  'base64'
).toString('utf-8');

const data = JSON.parse(raw);

let items = [];

if (Array.isArray(data)) {
  items = data;
} else if (Array.isArray(data.artigos)) {
  items = data.artigos;
} else if (Array.isArray(data.paginas)) {
  items = data.paginas;
} else if (Array.isArray(data.sites)) {
  items = data.sites;
} else if (Array.isArray(data.links)) {
  items = data.links;
} else {
  const firstArrayKey = Object.keys(data)
    .find(k => Array.isArray(data[k]));

  items = firstArrayKey
    ? data[firstArrayKey]
    : [data];
}

return items.map((item, i) => {

  const targetUrl =
    item.url ||
    item.link ||
    item.link_pdf ||
    item.link_site ||
    '';

  const titulo =
    item.titulo ||
    item.title ||
    item.nome ||
    `Regra ${i + 1}`;

  const categoria =
    item.categoria ||
    item.category ||
    item.tipo ||
    'regras_mtg';

  const cleanUrl = targetUrl
    .toLowerCase()
    .split('?')[0];

  const tipoFonte =
    cleanUrl.endsWith('.pdf')
      ? 'pdf'
      : 'html';

  return {
    json: {
      id: i + 1,
      titulo,
      url: targetUrl,
      categoria,
      tipo_fonte: tipoFonte
    }
  };
});

let docs = $input.all().map(i => i.json);
if (Array.isArray(docs[0])) docs = docs[0];

const clean = (s = '') => {
  return s
    .replace(/\u00ad/g, '')
    .split('\n')
    .filter(line => {
      const l = line.trim();
      if (!l) return false;
      // Filtros de cabeçalho, rodapé e lixo corporativo
      if (l.startsWith('Skip to main content')) return false;
      if (l.includes('MAGIC: THE GATHERING FOOTER') || l.includes('FIND A STORE')) return false;
      if (l.includes('ESRB Privacy') || l.includes('Privacy Policy') || l.includes('Terms [https:')) return false;
      if (l.includes('DO NOT SELL OR SHARE') || l.includes('Your Privacy Choices')) return false;
      if (l.includes('facebook.com') || l.includes('twitter.com') || l.includes('twitch.tv') || l.includes('instagram.com')) return false;
      if (l.includes('Coming Soon Coming Soon') || l.includes('Available Now Available Now')) return false;
      if (l.includes('The logo of Wizards of the Coast') || l.includes('The Logo of Hasbro')) return false;
      return true;
    })
    .join('\n')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n');
};

function chunkText(text, size = 800, overlap = 100) {
  const out = [];
  let i = 0;
  while (i < text.length) {
    const end = Math.min(i + size, text.length);
    out.push(text.slice(i, end));
    if (end === text.length) break;
    i = Math.max(0, end - overlap);
  }
  return out;
}

const out = [];
for (const d of docs) {
  const fullText = clean(d.text || d.conteudo || '');
  if (!fullText || fullText.length < 80) continue;

  const chunks = chunkText(fullText, 800, 100);
  const title = d.titulo || 'Regras de Magic';

  chunks.forEach((c, idx) => {
    const textContent = c.trim();
    // Descarta blocos pequenos que sobraram de links soltos
    if (textContent.length > 60) {
      out.push({
        json: {
          text: `[${title} - Parte ${idx + 1}/${chunks.length}]\n\n${textContent}`,
          metadata: {
            chunk: idx + 1,
            total_chunks: chunks.length
          }
        }
      });
    }
  });
}

return out;

const output = $json.output || '';

const parts = output
  .split('<!--SPLIT-->')
  .map(part => part.trim())
  .filter(Boolean);

for (let i = 0; i < parts.length; i++) {
  if (parts[i].length > 3800) {
    throw new Error(
      `A mensagem ${i + 1} ultrapassou o limite de segurança: ` +
      `${parts[i].length} caracteres.`
    );
  }
}

return parts.map((text, index) => ({
  json: {
    text,
    part: index + 1,
    totalParts: parts.length
  }
}));

const raw = $json.output || '';
return [{
  json: {
    output: raw.replaceAll('<!--SPLIT-->', '\n\n')
  }
}];

const raw = $json.output || '';

// 1. Remove o marcador de divisão do Telegram
let text = raw.replaceAll('<!--SPLIT-->', '\n\n');

// 2. Converte as tags HTML do agente para Markdown compatível com a Web
text = text
  .replace(/<\/?b>/gi, '**')       // <b> e </b> viram **negrito**
  .replace(/<\/?i>/gi, '*')        // <i> e </i> viram *itálico*
  .replace(/<\/?code>/gi, '`')     // <code> e </code> viram `código`
  .replace(/<br\s*\/?>/gi, '\n');  // Quebras de linha extras

return [{
  json: {
    output: text.trim()
  }
}];
